PRAGMA foreign_keys=ON;
CREATE TABLE meta(key TEXT PRIMARY KEY,value TEXT NOT NULL) STRICT;
CREATE TABLE settings(id INTEGER PRIMARY KEY CHECK(id=1),instance_name TEXT NOT NULL,registration_mode TEXT NOT NULL DEFAULT 'CLOSED' CHECK(registration_mode IN('CLOSED','INVITE','REGULAR','GUEST','BOTH')),created_at TEXT NOT NULL,updated_at TEXT NOT NULL) STRICT;
CREATE TABLE profile_fields(id TEXT PRIMARY KEY,key TEXT NOT NULL UNIQUE,label TEXT NOT NULL,data_type TEXT NOT NULL CHECK(data_type IN('TEXT','EMAIL','DATE','INTEGER','BOOLEAN')),regular_rule TEXT NOT NULL CHECK(regular_rule IN('HIDDEN','OPTIONAL','REQUIRED')),guest_rule TEXT NOT NULL CHECK(guest_rule IN('HIDDEN','OPTIONAL','REQUIRED')),show_optional_registration INTEGER NOT NULL DEFAULT 0 CHECK(show_optional_registration IN(0,1)),max_length INTEGER NOT NULL DEFAULT 255,sort_order INTEGER NOT NULL DEFAULT 0) STRICT;
CREATE TABLE objects(id TEXT PRIMARY KEY,type TEXT NOT NULL CHECK(type IN('USER','SPACE','GROUP','ROLE','SYSTEM')),subtype TEXT,name TEXT NOT NULL,description TEXT,status TEXT,created_by TEXT REFERENCES objects(id) ON DELETE SET NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,CHECK((type='SPACE' AND subtype IN('PRIVATE','FAMILY','ORGANIZATION')) OR(type<>'SPACE' AND subtype IS NULL)),CHECK((type='USER' AND status IS NULL) OR(type<>'USER' AND status IN('ACTIVE','DISABLED','ARCHIVED')))) STRICT;
CREATE TABLE users(id TEXT PRIMARY KEY REFERENCES objects(id) ON DELETE CASCADE,account_kind TEXT NOT NULL CHECK(account_kind IN('REGULAR','GUEST')),username TEXT NOT NULL UNIQUE COLLATE NOCASE,password_hash TEXT,totp_secret_enc TEXT,mfa_enabled INTEGER NOT NULL DEFAULT 0 CHECK(mfa_enabled IN(0,1)),preferred_auth TEXT NOT NULL CHECK(preferred_auth IN('PASSKEY','PASSWORD_TOTP')),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,CHECK(preferred_auth<>'PASSWORD_TOTP' OR(password_hash IS NOT NULL AND totp_secret_enc IS NOT NULL))) STRICT;
CREATE TABLE user_values(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,field_id TEXT NOT NULL REFERENCES profile_fields(id) ON DELETE CASCADE,value TEXT NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(user_id,field_id)) WITHOUT ROWID,STRICT;
CREATE TABLE passkeys(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,credential_id BLOB NOT NULL UNIQUE,public_key BLOB NOT NULL,sign_count INTEGER NOT NULL DEFAULT 0,transports TEXT NOT NULL DEFAULT '[]',name TEXT NOT NULL,created_at TEXT NOT NULL,last_used_at TEXT,revoked_at TEXT) STRICT;
CREATE TABLE challenges(id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id) ON DELETE CASCADE,purpose TEXT NOT NULL CHECK(purpose IN('REGISTER','LOGIN')),challenge BLOB NOT NULL,expires_at TEXT NOT NULL,used_at TEXT) STRICT;
CREATE TABLE systems(id TEXT PRIMARY KEY REFERENCES objects(id) ON DELETE CASCADE,domain TEXT NOT NULL UNIQUE COLLATE NOCASE,allowed_origin TEXT NOT NULL UNIQUE COLLATE NOCASE,auth_mode TEXT NOT NULL CHECK(auth_mode IN('API_KEY','MTLS')),api_key_hash TEXT,certificate_fingerprint TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,CHECK((auth_mode='API_KEY' AND api_key_hash IS NOT NULL) OR(auth_mode='MTLS' AND certificate_fingerprint IS NOT NULL))) STRICT;
CREATE TABLE permissions(id TEXT PRIMARY KEY,system_id TEXT NOT NULL REFERENCES systems(id) ON DELETE CASCADE,name TEXT NOT NULL,description TEXT,status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK(status IN('ACTIVE','DISABLED','ARCHIVED')),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(system_id,name COLLATE NOCASE)) STRICT;
CREATE TABLE assignments(id TEXT PRIMARY KEY,source_id TEXT NOT NULL REFERENCES objects(id) ON DELETE CASCADE,target_id TEXT REFERENCES objects(id) ON DELETE CASCADE,permission_id TEXT REFERENCES permissions(id) ON DELETE CASCADE,access TEXT NOT NULL CHECK(access IN('READ','READ_WRITE')),state TEXT NOT NULL CHECK(state IN('REQUESTED','ACCEPTED','DECLINED','CANCELLED')),requested_by TEXT NOT NULL REFERENCES users(id),requested_at TEXT NOT NULL,answered_by TEXT REFERENCES users(id),answered_at TEXT,updated_at TEXT NOT NULL,CHECK((target_id IS NOT NULL)<>(permission_id IS NOT NULL)),CHECK(target_id IS NULL OR source_id<>target_id)) STRICT;
CREATE TABLE data_grants(system_id TEXT NOT NULL REFERENCES systems(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,data_key TEXT NOT NULL,allowed INTEGER NOT NULL CHECK(allowed IN(0,1)),granted_by TEXT NOT NULL REFERENCES users(id),updated_at TEXT NOT NULL,PRIMARY KEY(system_id,user_id,data_key)) WITHOUT ROWID,STRICT;
CREATE TABLE sessions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_hash TEXT NOT NULL UNIQUE,csrf TEXT NOT NULL,expires_at TEXT NOT NULL,created_at TEXT NOT NULL) STRICT;
CREATE TABLE invitations(id TEXT PRIMARY KEY,account_kind TEXT NOT NULL CHECK(account_kind IN('REGULAR','GUEST')),token_hash TEXT NOT NULL UNIQUE,created_by TEXT NOT NULL REFERENCES users(id),expires_at TEXT NOT NULL,used_at TEXT,created_at TEXT NOT NULL) STRICT;
CREATE INDEX ix_assign_source ON assignments(source_id);CREATE INDEX ix_perm_system ON permissions(system_id);CREATE INDEX ix_challenge_expiry ON challenges(expires_at);
INSERT INTO meta VALUES('schema_version','1');
